using namespace std;

int main() {
    int n;
    cin >> n;

    long long prev2 = 0;
    long long prev1 = 1;

    if (n == 0) {
        cout << 0 << '
';
        return 0;
    }

    for (int i = 2; i <= n; i++) {
        long long cur = prev1 + prev2;
        prev2 = prev1;
        prev1 = cur;
    }

    cout << prev1 << '\n';
    return 0;
